"""Build commit-pinned source excerpts, never guessed line numbers."""
import json
from pathlib import Path
ROOT=Path(__file__).parent
REVISIONS={r['name']:r for r in json.loads((ROOT/'evidence/revisions.json').read_text()) if 'sha' in r}
S=[]
def add(id,repo,file,needle,title,count=45,offset=0):
    path=ROOT/'repos'/repo/file; lines=path.read_text().splitlines()
    found=next((i for i,line in enumerate(lines) if needle in line),None)
    if found is None:raise ValueError((id,file,needle))
    start=max(0,found+offset);end=min(len(lines),start+count);r=REVISIONS[repo]
    S.append(dict(id=id,repo=repo,file=file,title=title,sha=r['sha'],line=start+1,end=end,url=f"https://github.com/{r['repo']}/blob/{r['sha']}/{file}#L{start+1}-L{end}",kind='source',excerpt='\n'.join(f'{i+1:>5}  {lines[i]}' for i in range(start,end))))

