for id,file,url,title in [
 ('cloud-current','codex-current-cloud.html.txt','https://developers.openai.com/codex/environments/cloud-environments','Codex Cloud 当前环境：独立 workspace 与保存状态'),
 ('cloud-legacy','codex-cloud.html.txt','https://developers.openai.com/codex/cloud/environments','Codex Cloud Legacy：不要混用旧文档')]:
    S.append(dict(id=id,repo='official-doc',file=file,title=title,url=url,kind='official',excerpt=(ROOT/'evidence'/file).read_text()[:17000]))
for s in S:
    if s['file'].endswith('.md'):
        s['kind']='official'
(ROOT/'evidence/sources.json').write_text(json.dumps(S,ensure_ascii=False,indent=2))
print(f'{len(S)} pinned source/document entries')
